@prefix cdifd: <https://cdif.org/validation/0.1/shacl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix schema1: <http://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode 42 ;
            sh:resultMessage "schema:propertyID value looks like a URI or CURIE (prefix:localname) but is serialized as a string literal. Serialize URI values as JSON-LD IRI references: {\"@id\":\"...\"}. Free-label strings like 'temperature' remain valid as strings." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape cdifd:PropertyIDUriShouldBeIRIShape ;
            sh:value 42 ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/exampleAdditionalProperty_lkj09> ;
            sh:resultMessage "Node Literal(\"42\", datatype=xsd:integer) must conform to one or more shapes in [ sh:nodeKind sh:IRI ] , [ sh:datatype xsd:string ; sh:minLength Literal(\"5\", datatype=xsd:integer) ] , [ sh:class schema1:DefinedTerm ]" ;
            sh:resultPath schema1:propertyID ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape [ sh:minCount 1 ;
                    sh:or ( [ sh:nodeKind sh:IRI ] [ sh:datatype xsd:string ;
                                sh:minLength 5 ] [ sh:class schema1:DefinedTerm ] ) ;
                    sh:path schema1:propertyID ;
                    sh:severity sh:Warning ] ;
            sh:value 42 ] .

